  staff: 80,
  potion: 40,
};

export const processScenario = (scenario: Scenario): { results: Array<{ premium: number }> } => {
  const results = scenario.steps.map((step) => {
    const base = step.items.reduce((sum, item) => sum + (BASE_PREMIUM[item.type] ?? 0), 0);
    const premium = Math.ceil(base * 1.1) + 5;
    return { premium };
  });
  return { results };
};

