import { describe, it, expect } from "vitest";
import { processScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // Quoting - base items and processing fee
  it("quotes a single sword for a new customer (base + first-insurance surcharge + fee)", () => {
    const result = processScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
        },
      ],
    });
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("quotes an amulet, staff, and potion with proper base premiums", () => {
    const quote = (type: string) =>
      processScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type, material: "steel", enchantment: 1, cursed: false }] },
        ],
      });
    expect(quote("amulet")).toEqual({ results: [{ premium: 71 }] });
    expect(quote("staff")).toEqual({ results: [{ premium: 93 }] });
    expect(quote("potion")).toEqual({ results: [{ premium: 49 }] });
  });
  it.todo("quotes a single component (rune) at 25 G base");
  it.todo("quotes a building block of 3 alike components at 60 G special base premium");

  // Risk surcharges and discounts
  it.todo("applies 50% cursed surcharge on an item");
  it.todo("applies 30% high-enchantment surcharge for enchantment >= 5");
  it.todo("applies 20% loyalty discount when yearsWithMHPCO >= 2");
  it.todo("applies 15% repeat-contract discount from the second quote onwards");
  it.todo("rounds premium up to whole G (in MHPCO's favor)");

  // Claims
  it.todo("pays a claim minus 100 G deductible, rounded in MHPCO's favor");
  it.todo("caps total payout at twice the insurance sum of the policy");
  it.todo("reimburses damage to items with enchantment >= 8 at 50%");
  it.todo("fully reimburses damage to dragon-material items (no 50% reduction)");
});

