type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
type QuoteStep = { op: "quote"; items: Item[] };
type Step = QuoteStep;
type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const BUILDING_BLOCK_PREMIUM = 60;

const basePremiumForItems = (items: Item[]): number => {
  const componentCounts: Record<string, number> = {};
  let total = 0;
  for (const item of items) {
    if (COMPONENT_TYPES.has(item.type)) {
      componentCounts[item.type] = (componentCounts[item.type] ?? 0) + 1;
    } else {
      total += BASE_PREMIUM[item.type] ?? 0;
    }
  }
  for (const type of Object.keys(componentCounts)) {
    const count = componentCounts[type];
    const blocks = Math.floor(count / 3);
    const leftovers = count % 3;
    total += blocks * BUILDING_BLOCK_PREMIUM + leftovers * BASE_PREMIUM[type];
  }
  return total;
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const roundUpInMHPCOFavor = (value: number): number =>
  Math.ceil(Math.round(value * 100) / 100);

export const processScenario = (scenario: Scenario): { results: Array<{ premium: number }> } => {
  const results = scenario.steps.map((step) => {
    const base = basePremiumForItems(step.items);
    const premium = roundUpInMHPCOFavor(base * (1 + FIRST_INSURANCE_SURCHARGE)) + PROCESSING_FEE;
    return { premium };
  });
  return { results };
};

